<style>
  :root {
    --hh: 64px;
    --bg: #f2f5f1;
    --surface: #ffffff;
    --ink: #16241f;
    --muted: #5a6b64;
    --line: #dae2dc;
    --hover: #e6ede8;
    --accent: #0f6b56;
    --accent-ink: #ffffff;
    --gold: #d4a94a;
    --head-bg: #0c4a3d;
    --head-ink: #ffffff;
    --head-muted: #b5d3c8;
    --code-bg: #0f1d19;
    --code-bar: #172b25;
    --code-ink: #dbeae4;
    --code-muted: #8fb0a4;
    --ok: #3ddc97;
    --font-ui: "Noto Sans Bengali", "Hind Siliguri", "Kalpurush", "Nirmala UI", "Segoe UI", system-ui, -apple-system, sans-serif;
    --font-code: "JetBrains Mono", "Fira Code", ui-monospace, "SF Mono", Consolas, monospace;
  }
  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) {
      --bg: #0b1310; --surface: #111f1a; --ink: #e5efe9; --muted: #92a89e;
      --line: #22352d; --hover: #1a2c25; --accent: #4fc3a1; --accent-ink: #062018;
      --head-bg: #08322a; --code-bg: #080f0d; --code-bar: #12231e;
    }
  }
  :root[data-theme="dark"] {
    --bg: #0b1310; --surface: #111f1a; --ink: #e5efe9; --muted: #92a89e;
    --line: #22352d; --hover: #1a2c25; --accent: #4fc3a1; --accent-ink: #062018;
    --head-bg: #08322a; --code-bg: #080f0d; --code-bar: #12231e;
  }

  * { box-sizing: border-box; }
  html { scroll-behavior: smooth; scroll-padding-top: calc(var(--hh) + 12px); }
  body {
    margin: 0; background: var(--bg); color: var(--ink);
    font-family: var(--font-ui); line-height: 1.7;
    -webkit-text-size-adjust: 100%;
  }
  button { font-family: inherit; }

  /* ---------- Header ---------- */
  .top {
    position: sticky; top: 0; z-index: 30;
    height: var(--hh);
    background: var(--head-bg); color: var(--head-ink);
    border-bottom: 3px solid var(--gold);
  }
  .top-in {
    max-width: 1240px; height: 100%; margin: 0 auto; padding: 0 16px;
    display: flex; align-items: center; gap: 14px;
  }
  .brand { display: flex; align-items: center; gap: 12px; min-width: 0; color: inherit; text-decoration: none; margin-right: auto; }
  .logo { flex: none; width: 42px; height: 42px; border-radius: 10px; overflow: hidden; display: grid; place-items: center; }
  .logo img, .logo svg { width: 100%; height: 100%; object-fit: contain; display: block; }
  .brand-text { display: flex; flex-direction: column; min-width: 0; line-height: 1.25; }
  .brand-text b { font-size: 1.3rem; font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .brand-text small { color: var(--head-muted); font-size: 0.8rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

  .hbtn {
    flex: none; padding: 7px 13px;
    border: 1px solid rgba(255,255,255,0.28); border-radius: 8px;
    background: transparent; color: var(--head-ink);
    font-size: 0.88rem; cursor: pointer;
  }
  .hbtn:hover { background: rgba(255,255,255,0.1); }
  #navBtn { display: none; }

  /* ---------- Layout ---------- */
  .shell {
    max-width: 1240px; margin: 0 auto; padding: 20px 16px 72px;
    display: grid; grid-template-columns: 290px minmax(0, 1fr); gap: 28px;
  }

  /* ---------- Sidebar / menu tree ---------- */
  .side {
    position: sticky; top: calc(var(--hh) + 16px);
    align-self: start;
    max-height: calc(100vh - var(--hh) - 32px);
    overflow-y: auto;
    background: var(--surface); border: 1px solid var(--line); border-radius: 12px;
    padding: 12px;
  }
  .side-title { margin: 2px 4px 8px; font-size: 0.85rem; color: var(--muted); font-weight: 600; }
  .msearch {
    width: 100%; margin-bottom: 10px; padding: 8px 12px;
    border: 1px solid var(--line); border-radius: 8px;
    background: var(--bg); color: var(--ink); font: inherit; font-size: 0.92rem;
  }
  .msearch::placeholder { color: var(--muted); }

  .tree, .tree ul { list-style: none; margin: 0; padding: 0; }
  .tree ul { margin-left: 13px; padding-left: 6px; border-left: 1px solid var(--line); }
  .row { display: flex; align-items: center; border-radius: 8px; }
  .row:hover { background: var(--hover); }
  .chev {
    flex: none; width: 30px; height: 34px; border: 0; background: transparent;
    color: var(--muted); cursor: pointer; border-radius: 6px;
    display: grid; place-items: center;
  }
  .chev::before {
    content: ""; width: 6px; height: 6px;
    border-right: 2px solid currentColor; border-bottom: 2px solid currentColor;
    transform: rotate(-45deg); transition: transform .15s;
  }
  .chev[aria-expanded="true"]::before { transform: rotate(45deg); }
  .spacer { flex: none; width: 30px; }
  .lab {
    flex: 1; min-width: 0; text-align: left; padding: 6px 4px;
    border: 0; background: transparent; color: var(--ink);
    font-size: 0.94rem; cursor: pointer; overflow-wrap: anywhere;
  }
  .cnt { flex: none; padding: 0 9px; font-size: 0.78rem; color: var(--muted); }
  .row.onpath .lab { font-weight: 600; }
  .row.dim .lab { color: var(--muted); }
  .row.active { background: var(--accent); }
  .row.active .lab, .row.active .cnt, .row.active .chev { color: var(--accent-ink); }
  .row.active .lab { font-weight: 700; }
  .none { margin: 8px 4px; font-size: 0.9rem; color: var(--muted); }

  /* ---------- Main ---------- */
  .crumbs { display: flex; flex-wrap: wrap; align-items: center; gap: 4px; margin-bottom: 6px; font-size: 0.88rem; }
  .crumbs button, .trail button {
    padding: 0; border: 0; background: none; color: var(--muted); font-size: inherit; cursor: pointer;
  }
  .crumbs button:hover, .trail button:hover { color: var(--accent); text-decoration: underline; }
  .crumbs .sep, .trail .sep { color: var(--muted); opacity: .6; }
  .crumbs .here { color: var(--ink); font-weight: 600; }

  .head-row { display: flex; align-items: baseline; gap: 12px; flex-wrap: wrap; margin-bottom: 14px; }
  .head-row h2 { margin: 0; font-size: 1.5rem; line-height: 1.35; }
  .head-row .meta { color: var(--muted); font-size: 0.9rem; }

  .tiles-title { margin: 0 0 8px; font-size: 0.88rem; color: var(--muted); font-weight: 600; }
  .tiles { display: grid; grid-template-columns: repeat(auto-fill, minmax(170px, 1fr)); gap: 10px; margin-bottom: 22px; }
  .tile {
    display: flex; justify-content: space-between; align-items: center; gap: 8px;
    padding: 11px 14px; text-align: left;
    border: 1px solid var(--line); border-left: 4px solid var(--gold); border-radius: 10px;
    background: var(--surface); color: var(--ink); font-size: 0.95rem; cursor: pointer;
  }
  .tile:hover { border-color: var(--accent); border-left-color: var(--accent); }
  .tile small { color: var(--muted); }

  .search {
    width: 100%; margin-bottom: 18px; padding: 12px 16px;
    border: 1px solid var(--line); border-radius: 10px;
    background: var(--surface); color: var(--ink); font: inherit; font-size: 1rem;
  }
  .search::placeholder { color: var(--muted); }

  .list { display: flex; flex-direction: column; gap: 22px; }
  .entry {
    background: var(--surface); border: 1px solid var(--line);
    border-radius: 12px; padding: 20px; min-width: 0;
  }
  .trail { display: flex; flex-wrap: wrap; gap: 4px; margin: 0 0 4px; font-size: 0.82rem; }
  .trail button { color: var(--accent); font-weight: 600; }
  .entry h3 { margin: 0 0 6px; font-size: 1.2rem; line-height: 1.4; }
  .entry .desc { margin: 0 0 16px; color: var(--muted); white-space: pre-wrap; max-width: 70ch; }

  /* ---------- Code box: label left, copy right ---------- */
  .codebox { border-radius: 8px; overflow: hidden; background: var(--code-bg); }
  .codebar {
    display: flex; justify-content: space-between; align-items: center; gap: 12px;
    padding: 8px 8px 8px 14px; background: var(--code-bar);
  }
  .label { display: flex; align-items: center; gap: 10px; min-width: 0; }
  .lang {
    flex: none; padding: 2px 10px; border-radius: 999px;
    background: var(--tag, #0f6b56); color: #fff;
    font-family: var(--font-code); font-size: 0.78rem; font-weight: 600;
  }
  .fname {
    color: var(--code-muted); font-family: var(--font-code); font-size: 0.82rem;
    overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  }
  .copy {
    flex: none; min-width: 84px; padding: 6px 14px;
    border: 1px solid rgba(255,255,255,0.2); border-radius: 6px;
    background: transparent; color: var(--code-ink); font-size: 0.85rem; cursor: pointer;
    transition: background .15s, border-color .15s, color .15s;
  }
  .copy:hover { background: rgba(255,255,255,0.08); }
  .copy.done { border-color: var(--ok); color: var(--ok); }
  pre {
    margin: 0; padding: 16px 18px; overflow: auto; color: var(--code-ink);
    font-family: var(--font-code); font-size: 0.88rem; line-height: 1.65; tab-size: 2;
  }
  pre code { font: inherit; white-space: pre; }
  .collapsed pre { max-height: 300px; overflow: hidden; }
  .more {
    display: block; width: 100%; padding: 8px;
    border: 0; border-top: 1px solid rgba(255,255,255,0.08);
    background: var(--code-bar); color: var(--code-muted); font-size: 0.85rem; cursor: pointer;
  }
  .more:hover { color: var(--code-ink); }

  .notice {
    padding: 20px; border: 1px dashed var(--line); border-radius: 12px; color: var(--muted);
  }
  .notice code { font-family: var(--font-code); background: var(--surface); padding: 1px 6px; border-radius: 4px; color: var(--ink); }
  .notice strong { color: var(--ink); }
  .notice button {
    margin-top: 10px; padding: 7px 14px; border: 1px solid var(--accent); border-radius: 8px;
    background: transparent; color: var(--accent); cursor: pointer; font-size: 0.9rem;
  }

  :focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }

  /* ---------- Mobile: menu becomes a slide-in drawer ---------- */
  .scrim { display: none; }
  @media (max-width: 800px) {
    :root { --hh: 58px; }
    .logo { width: 38px; height: 38px; }
    .brand-text b { font-size: 1.1rem; }
    .brand-text small { display: none; }
    #navBtn { display: inline-block; }
    #themeBtn { display: none; }
    .shell { grid-template-columns: minmax(0, 1fr); padding-top: 14px; }
    .side {
      position: fixed; z-index: 50; top: 0; left: 0; bottom: 0;
      width: min(86vw, 330px); max-height: none; border-radius: 0 12px 12px 0;
      align-self: stretch; height: 100vh; height: 100dvh;
      padding-top: 16px;
      transform: translateX(-102%); transition: transform .22s ease;
    }
    body.nav-open .side { transform: none; }
    body.nav-open .scrim {
      display: block; position: fixed; inset: 0; z-index: 40; background: rgba(0,0,0,0.45);
    }
    .entry { padding: 16px; }
    .head-row h2 { font-size: 1.3rem; }
  }
  @media (prefers-reduced-motion: reduce) {
    html { scroll-behavior: auto; }
    .side, .chev::before, .copy { transition: none; }
  }
</style>
</head>
