<script>
(function () {
  "use strict";

  var DATA_URL = "data.json";
  var DEFAULT_TITLE = "কোরআনের ফেরিওয়ালা";
  var COLLAPSE_LINES = 18;
  var LANG_COLORS = {
    "html": "#e34c26", "css": "#2965f1", "json": "#8a6d00", "python": "#3776ab",
    "node": "#3c873a", "javascript": "#b58900", "typescript": "#3178c6",
    "bash": "#2f855a", "shell": "#2f855a", "php": "#777bb4", "java": "#c2571a",
    "c": "#5a6a7d", "c++": "#00599c", "c#": "#68217a", "go": "#00a7c4",
    "rust": "#b7410e", "sql": "#c05621", "yaml": "#a3293d", "xml": "#7a5c99",
    "markdown": "#4a5568", "text": "#4a5568"
  };

  var state = { data: null, root: null, map: {}, path: [], expanded: {}, query: "", menuQuery: "", rootLabel: "সব" };
  var $ = function (id) { return document.getElementById(id); };
  var el = {
    logo: $("logo"), title: $("siteTitle"), tag: $("siteTag"),
    tree: $("tree"), msearch: $("msearch"), crumbs: $("crumbs"),
    pageTitle: $("pageTitle"), pageMeta: $("pageMeta"),
    tilesWrap: $("tilesWrap"), search: $("search"), list: $("list"),
    navBtn: $("navBtn"), scrim: $("scrim"), theme: $("themeBtn")
  };

  /* ---------- helpers ---------- */
  var BN = "০১২৩৪৫৬৭৮৯";
  function bn(n) { return String(n).replace(/\d/g, function (d) { return BN[d]; }); }
  function keyOf(path) { return path.map(encodeURIComponent).join("/"); }
  function isPrefix(prefix, path) {
    if (prefix.length > path.length) return false;
    for (var i = 0; i < prefix.length; i++) if (prefix[i] !== path[i]) return false;
    return true;
  }
  function itemPath(it) {
    if (Array.isArray(it.path) && it.path.length) return it.path;
    return it.menu ? [it.menu] : [];   // পুরোনো data.json এর সাথে সামঞ্জস্য
  }
  function isMobile() { return window.matchMedia("(max-width: 800px)").matches; }
