  .head-row h2 { margin: 0; font-size: 1.5rem; line-height: 1.35; }
  .head-row .meta { color: var(--muted); font-size: 0.9rem; }

  .tiles-title { margin: 0 0 8px; font-size: 0.88rem; color: var(--muted); font-weight: 600; }
  .tiles { display: grid; grid-template-columns: repeat(auto-fill, minmax(170px, 1fr)); gap: 10px; margin-bottom: 22px; }
  .tile {
    display: flex; justify-content: space-between; align-items: center; gap: 8px;
    padding: 11px 14px; text-align: left;
    border: 1px solid var(--line); border-left: 4px solid var(--gold); border-radius: 10px;
    background: var(--surface); color: var(--ink); font-size: 0.95rem; cursor: pointer;
  }
  .tile:hover { border-color: var(--accent); border-left-color: var(--accent); }
  .tile small { color: var(--muted); }

  .search {
    width: 100%; margin-bottom: 18px; padding: 12px 16px;
    border: 1px solid var(--line); border-radius: 10px;
    background: var(--surface); color: var(--ink); font: inherit; font-size: 1rem;
  }
  .search::placeholder { color: var(--muted); }

  .list { display: flex; flex-direction: column; gap: 22px; }
  .entry {
    background: var(--surface); border: 1px solid var(--line);
    border-radius: 12px; padding: 20px; min-width: 0;
  }
  .trail { display: flex; flex-wrap: wrap; gap: 4px; margin: 0 0 4px; font-size: 0.82rem; }
  .trail button { color: var(--accent); font-weight: 600; }
  .entry h3 { margin: 0 0 6px; font-size: 1.2rem; line-height: 1.4; }
  .entry .desc { margin: 0 0 16px; color: var(--muted); white-space: pre-wrap; max-width: 70ch; }

  /* ---------- Code box: label left, copy right ---------- */
  .codebox { border-radius: 8px; overflow: hidden; background: var(--code-bg); }
  .codebar {
    display: flex; justify-content: space-between; align-items: center; gap: 12px;
    padding: 8px 8px 8px 14px; background: var(--code-bar);
  }
  .label { display: flex; align-items: center; gap: 10px; min-width: 0; }
  .lang {
    flex: none; padding: 2px 10px; border-radius: 999px;
    background: var(--tag, #0f6b56); color: #fff;
    font-family: var(--font-code); font-size: 0.78rem; font-weight: 600;
  }
  .fname {
    color: var(--code-muted); font-family: var(--font-code); font-size: 0.82rem;
    overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  }
  .copy {
    flex: none; min-width: 84px; padding: 6px 14px;
    border: 1px solid rgba(255,255,255,0.2); border-radius: 6px;
    background: transparent; color: var(--code-ink); font-size: 0.85rem; cursor: pointer;
    transition: background .15s, border-color .15s, color .15s;
  }
  .copy:hover { background: rgba(255,255,255,0.08); }
  .copy.done { border-color: var(--ok); color: var(--ok); }
  pre {
    margin: 0; padding: 16px 18px; overflow: auto; color: var(--code-ink);
    font-family: var(--font-code); font-size: 0.88rem; line-height: 1.65; tab-size: 2;
  }
  pre code { font: inherit; white-space: pre; }
  .collapsed pre { max-height: 300px; overflow: hidden; }
  .more {
    display: block; width: 100%; padding: 8px;
    border: 0; border-top: 1px solid rgba(255,255,255,0.08);
    background: var(--code-bar); color: var(--code-muted); font-size: 0.85rem; cursor: pointer;
  }
  .more:hover { color: var(--code-ink); }

  .notice {
    padding: 20px; border: 1px dashed var(--line); border-radius: 12px; color: var(--muted);
  }
  .notice code { font-family: var(--font-code); background: var(--surface); padding: 1px 6px; border-radius: 4px; color: var(--ink); }
  .notice strong { color: var(--ink); }
  .notice button {
    margin-top: 10px; padding: 7px 14px; border: 1px solid var(--accent); border-radius: 8px;
    background: transparent; color: var(--accent); cursor: pointer; font-size: 0.9rem;
  }

  :focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }

  /* ---------- Mobile: menu becomes a slide-in drawer ---------- */
  .scrim { display: none; }
  @media (max-width: 800px) {
    :root { --hh: 58px; }
    .logo { width: 38px; height: 38px; }
    .brand-text b { font-size: 1.1rem; }
    .brand-text small { display: none; }
    #navBtn { display: inline-block; }
    #themeBtn { display: none; }
    .shell { grid-template-columns: minmax(0, 1fr); padding-top: 14px; }
    .side {
      position: fixed; z-index: 50; top: 0; left: 0; bottom: 0;
      width: min(86vw, 330px); max-height: none; border-radius: 0 12px 12px 0;
      align-self: stretch; height: 100vh; height: 100dvh;
      padding-top: 16px;
      transform: translateX(-102%); transition: transform .22s ease;
    }
    body.nav-open .side { transform: none; }
    body.nav-open .scrim {
      display: block; position: fixed; inset: 0; z-index: 40; background: rgba(0,0,0,0.45);
    }
    .entry { padding: 16px; }
    .head-row h2 { font-size: 1.3rem; }
  }
  @media (prefers-reduced-motion: reduce) {
    html { scroll-behavior: auto; }
    .side, .chev::before, .copy { transition: none; }
  }
</style>
</head>
<body>

<header class="top">
  <div class="top-in">
    <button class="hbtn" id="navBtn" type="button" aria-label="মেনু খুলুন">☰ মেনু</button>
    <a class="brand" href="#/">
      <span class="logo" id="logo">
        <svg viewBox="0 0 40 40" aria-hidden="true">
          <defs><mask id="cm"><rect width="40" height="40" fill="#fff"/><circle cx="25" cy="17" r="9" fill="#000"/></mask></defs>
          <rect width="40" height="40" rx="10" fill="#d4a94a"/>
          <circle cx="19" cy="21" r="11" fill="#0c4a3d" mask="url(#cm)"/>
        </svg>
      </span>
      <span class="brand-text">
        <b id="siteTitle">কোরআনের ফেরিওয়ালা</b>
        <small id="siteTag">CodeCraft</small>
      </span>
    </a>
    <button class="hbtn" id="themeBtn" type="button">থিম বদলান</button>
  </div>
</header>
<div class="scrim" id="scrim"></div>

<div class="shell">
  <aside class="side" id="side" aria-label="মেনু">
    <p class="side-title">মেনু</p>
    <input class="msearch" id="msearch" type="search" placeholder="মেনু খুঁজুন…" aria-label="মেনু খুঁজুন">
    <nav id="tree"></nav>
  </aside>

  <main id="main">
    <div class="crumbs" id="crumbs"></div>
    <div class="head-row"><h2 id="pageTitle"></h2><span class="meta" id="pageMeta"></span></div>
    <div id="tilesWrap"></div>
    <input class="search" id="search" type="search" placeholder="এই মেনুর ভেতরে শিরোনাম, বিবরণ বা কোড খুঁজুন…" aria-label="খুঁজুন">
    <div class="list" id="list"></div>
  </main>
</div>

<script>
(function () {
  "use strict";

  var DATA_URL = "data.json";
  var DEFAULT_TITLE = "কোরআনের ফেরিওয়ালা";
  var COLLAPSE_LINES = 18;
  var LANG_COLORS = {
    "html": "#e34c26", "css": "#2965f1", "json": "#8a6d00", "python": "#3776ab",
    "node": "#3c873a", "javascript": "#b58900", "typescript": "#3178c6",
    "bash": "#2f855a", "shell": "#2f855a", "php": "#777bb4", "java": "#c2571a",
    "c": "#5a6a7d", "c++": "#00599c", "c#": "#68217a", "go": "#00a7c4",
    "rust": "#b7410e", "sql": "#c05621", "yaml": "#a3293d", "xml": "#7a5c99",
    "markdown": "#4a5568", "text": "#4a5568"
  };

  var state = { data: null, root: null, map: {}, path: [], expanded: {}, query: "", menuQuery: "", rootLabel: "সব" };
  var $ = function (id) { return document.getElementById(id); };
  var el = {
    logo: $("logo"), title: $("siteTitle"), tag: $("siteTag"),
    tree: $("tree"), msearch: $("msearch"), crumbs: $("crumbs"),
    pageTitle: $("pageTitle"), pageMeta: $("pageMeta"),
    tilesWrap: $("tilesWrap"), search: $("search"), list: $("list"),
    navBtn: $("navBtn"), scrim: $("scrim"), theme: $("themeBtn")
  };

  /* ---------- helpers ---------- */
  var BN = "০১২৩৪৫৬৭৮৯";
  function bn(n) { return String(n).replace(/\d/g, function (d) { return BN[d]; }); }
  function keyOf(path) { return path.map(encodeURIComponent).join("/"); }
  function isPrefix(prefix, path) {
    if (prefix.length > path.length) return false;
    for (var i = 0; i < prefix.length; i++) if (prefix[i] !== path[i]) return false;
    return true;
  }
  function itemPath(it) {
    if (Array.isArray(it.path) && it.path.length) return it.path;
    return it.menu ? [it.menu] : [];   // পুরোনো data.json এর সাথে সামঞ্জস্য
  }
  function isMobile() { return window.matchMedia("(max-width: 800px)").matches; }
  function closeDrawer() { document.body.classList.remove("nav-open"); }

  /* ---------- load ---------- */
  fetch(DATA_URL, { cache: "no-store" })
    .then(function (r) { if (!r.ok) throw new Error("HTTP " + r.status); return r.json(); })
    .then(function (data) { state.data = data; init(); })
    .catch(showLoadError);

  function showLoadError(err) {
    el.list.innerHTML = "";
    var box = document.createElement("div");
    box.className = "notice";
    box.innerHTML = location.protocol === "file:"
      ? "<strong>data.json লোড করা যায়নি।</strong><br>ব্রাউজার সরাসরি ফাইল খুলে JSON পড়তে দেয় না। প্রজেক্ট ফোল্ডারে টার্মিনালে চালান: <code>python add.py serve</code> — তারপর <code>http://localhost:8000</code> খুলুন।"
      : "<strong>data.json লোড করা যায়নি।</strong><br>ফাইলটি index.html এর পাশেই আছে কি না এবং JSON ঠিক আছে কি না দেখুন।";
    el.list.appendChild(box);
    console.error("CodeCraft:", err);
  }

  /* ---------- tree building ---------- */
  function buildTree(data) {
    var root = { name: "", path: [], key: "", children: [], count: 0 };
    var map = { "": root };

    function ensure(path) {
      var cur = root;
      for (var i = 0; i < path.length; i++) {
        var name = path[i];
        var next = cur.children.filter(function (c) { return c.name === name; })[0];
        if (!next) {
          var p = path.slice(0, i + 1);
          next = { name: name, path: p, key: keyOf(p), children: [], count: 0 };
          cur.children.push(next);
          map[next.key] = next;
        }
        cur = next;
      }
      return cur;
    }
    function addMenus(list, base) {
      (list || []).forEach(function (m) {
        var name = typeof m === "string" ? m : m.name;
        var p = base.concat([name]);
        ensure(p);
        if (m && typeof m === "object") addMenus(m.children, p);
      });
    }
    addMenus(data.menus, []);

    (data.items || []).forEach(function (it) {
      it._path = itemPath(it);
      ensure(it._path);
      root.count++;
      for (var i = 1; i <= it._path.length; i++) map[keyOf(it._path.slice(0, i))].count++;
    });
    state.root = root;
    state.map = map;
  }

  function items() { return (state.data && state.data.items) || []; }
  function currentNode() { return state.map[keyOf(state.path)] || state.root; }

  /* ---------- init ---------- */
  function init() {
    var site = state.data.site || {};
    var title = site.title && site.title !== "CodeCraft" ? site.title : DEFAULT_TITLE;
    el.title.textContent = title;
    el.tag.textContent = site.tagline || site.subtitle || "CodeCraft";
    document.title = title + " — CodeCraft";
    state.rootLabel = site.root_label || "সব";
    setLogo(site.logo);
    buildTree(state.data);
    applyHash();
  }

  function setLogo(src) {
    if (!src) return;
    var img = new Image();
    img.alt = "";
    img.onload = function () { el.logo.innerHTML = ""; el.logo.appendChild(img); };
    img.src = src;   // না পেলে ডিফল্ট লোগোই থাকবে
  }

  /* ---------- navigation ---------- */
  function navigate(path) {
    var h = "#/" + keyOf(path);
    if (location.hash === h) applyHash(); else location.hash = h;
  }

  function applyHash() {
    var raw = location.hash.replace(/^#\/?/, "");
    var path = [];
    try { path = raw ? raw.split("/").map(decodeURIComponent) : []; } catch (e) { path = []; }
    if (!state.map[keyOf(path)]) path = [];
    state.path = path;
    for (var i = 1; i <= path.length; i++) state.expanded[keyOf(path.slice(0, i))] = true;
    renderAll();
    window.scrollTo({ top: 0 });
  }
  window.addEventListener("hashchange", function () { if (state.data) applyHash(); });

  /* ---------- render: all ---------- */
  function renderAll() { renderTree(); renderMain(); }

  /* ---------- render: sidebar tree ---------- */
  function renderTree() {
    el.tree.innerHTML = "";
    var q = state.menuQuery.trim().toLowerCase();
    var curKey = keyOf(state.path);

    function matches(n) { return n.name.toLowerCase().indexOf(q) !== -1; }
    function visible(n) { return !q || matches(n) || n.children.some(visible); }

    // "সব" — মূল সারি
    var top = document.createElement("ul");
    top.className = "tree";
    top.appendChild(makeRow(state.root, state.rootLabel, true));
    el.tree.appendChild(top);

    var any = false;
    function build(nodes, parentUl, forceAll) {
      nodes.forEach(function (n) {
        if (!(forceAll || visible(n))) return;
        any = true;
        var li = makeRow(n, n.name, false);
        parentUl.appendChild(li);
        var hasKids = n.children.length > 0;
        var open = q ? hasKids : !!state.expanded[n.key];
        if (hasKids && open) {
          var ul = document.createElement("ul");
          build(n.children, ul, q && matches(n));
          li.appendChild(ul);
        }
      });
    }
    build(state.root.children, top, false);

    if (q && !any) {
      var p = document.createElement("p");
      p.className = "none";
      p.textContent = "কোনো মেনু পাওয়া যায়নি।";
      el.tree.appendChild(p);
    }

    function makeRow(n, label, isRoot) {
      var li = document.createElement("li");
      var row = document.createElement("div");
      row.className = "row";
      var active = n.key === curKey;
      if (active) row.classList.add("active");
      else if (!isRoot && isPrefix(n.path, state.path)) row.classList.add("onpath");
      if (n.count === 0 && !isRoot) row.classList.add("dim");

      var hasKids = n.children.length > 0;
      if (hasKids && !isRoot) {
        var chev = document.createElement("button");
        chev.type = "button";
        chev.className = "chev";
        var open = q ? true : !!state.expanded[n.key];
        chev.setAttribute("aria-expanded", String(open));
        chev.setAttribute("aria-label", n.name + " — সাব মেনু খুলুন/বন্ধ করুন");
        chev.addEventListener("click", function () {
          state.expanded[n.key] = !state.expanded[n.key];
          renderTree();
        });
        row.appendChild(chev);
      } else {
        var sp = document.createElement("span");
        sp.className = "spacer";
        row.appendChild(sp);
      }

      var lab = document.createElement("button");
      lab.type = "button";
      lab.className = "lab";
      lab.textContent = label;
      if (active) lab.setAttribute("aria-current", "true");
      lab.addEventListener("click", function () {
        if (hasKids && !isRoot) state.expanded[n.key] = true;
        navigate(n.path);
        if (isMobile() && (!hasKids || isRoot)) closeDrawer();   // মোবাইলে শেষ ধাপে ড্রয়ার বন্ধ
      });
      row.appendChild(lab);

      var cnt = document.createElement("span");
      cnt.className = "cnt";
      cnt.textContent = bn(n.count);
      row.appendChild(cnt);

      li.appendChild(row);
      return li;
    }
  }

  /* ---------- render: main ---------- */
  function renderMain() {
    var node = currentNode();
    var isRoot = state.path.length === 0;

    // breadcrumb
    el.crumbs.innerHTML = "";
    var segs = [{ name: state.rootLabel, path: [] }];
    state.path.forEach(function (name, i) { segs.push({ name: name, path: state.path.slice(0, i + 1) }); });
    segs.forEach(function (s, i) {
      if (i > 0) { var sep = document.createElement("span"); sep.className = "sep"; sep.textContent = "›"; el.crumbs.appendChild(sep); }
      if (i === segs.length - 1 && i > 0) {
        var here = document.createElement("span"); here.className = "here"; here.textContent = s.name; el.crumbs.appendChild(here);
      } else {
        var b = document.createElement("button"); b.type = "button"; b.textContent = s.name;
        b.addEventListener("click", function () { navigate(s.path); });
        el.crumbs.appendChild(b);
      }
    });

    // title
    el.pageTitle.textContent = isRoot ? state.rootLabel : node.name;

    // sub-menu tiles
    el.tilesWrap.innerHTML = "";
    if (node.children.length && !state.query) {
      var t = document.createElement("p");
      t.className = "tiles-title";
      t.textContent = isRoot ? "মেনু বেছে নিন" : "সাব মেনু";
      var grid = document.createElement("div");
      grid.className = "tiles";
      node.children.forEach(function (c) {
        var b = document.createElement("button");
        b.type = "button"; b.className = "tile";
        var n = document.createElement("span"); n.textContent = c.name;
        var k = document.createElement("small"); k.textContent = bn(c.count);
        b.appendChild(n); b.appendChild(k);
        b.addEventListener("click", function () { navigate(c.path); });
        grid.appendChild(b);
      });
      el.tilesWrap.appendChild(t);
      el.tilesWrap.appendChild(grid);
    }

    // entries
    var shown = items().filter(function (it) { return isPrefix(state.path, it._path) && matchQuery(it); });
    el.pageMeta.textContent = bn(shown.length) + " টি এন্ট্রি" + (state.query ? " (খোঁজার ফলাফল)" : "");
    el.list.innerHTML = "";

    if (!shown.length) {
      var e = document.createElement("div");
      e.className = "notice";
      if (state.query) {
        e.textContent = "এই মেনুতে কিছু পাওয়া যায়নি।";
        if (!isRoot) {
          e.appendChild(document.createElement("br"));
          var all = document.createElement("button");
          all.type = "button"; all.textContent = "সব মেনুতে খুঁজুন";
          all.addEventListener("click", function () { navigate([]); });
          e.appendChild(all);
        }
      } else {
        e.innerHTML = items().length === 0
          ? "এখনও কিছু যোগ হয়নি। <code>python add.py</code> চালিয়ে প্রথম এন্ট্রি যোগ করুন।"
          : "এই মেনুতে এখনও কিছু নেই। <code>python add.py</code> চালিয়ে যোগ করুন।";
      }
      el.list.appendChild(e);
      return;
    }
    shown.slice().reverse().forEach(function (it) { el.list.appendChild(card(it)); });
  }

  function matchQuery(it) {
    if (!state.query) return true;
    var hay = [it.title, it.description, it.filename, it.language, it.code, it._path.join(" ")].join("\n").toLowerCase();
    return hay.indexOf(state.query) !== -1;
  }

  /* ---------- card ---------- */
  function card(it) {
    var art = document.createElement("article");
    art.className = "entry";

    if (it._path.length) {
      var trail = document.createElement("div");
      trail.className = "trail";
      it._path.forEach(function (name, i) {
        if (i > 0) { var s = document.createElement("span"); s.className = "sep"; s.textContent = "›"; trail.appendChild(s); }
        var b = document.createElement("button");
        b.type = "button"; b.textContent = name;
        b.addEventListener("click", function () { navigate(it._path.slice(0, i + 1)); });
        trail.appendChild(b);
      });
      art.appendChild(trail);
    }

    var h = document.createElement("h3");
    h.textContent = it.title || "(শিরোনাম নেই)";
    art.appendChild(h);

    if (it.description) {
      var d = document.createElement("p");
      d.className = "desc";
      d.textContent = it.description;
      art.appendChild(d);
    }
    if (it.code) art.appendChild(codeBox(it));
    return art;
  }

  function codeBox(it) {
    var box = document.createElement("div");
    box.className = "codebox";

    var bar = document.createElement("div");
    bar.className = "codebar";

    var label = document.createElement("div");
    label.className = "label";
    var lang = document.createElement("span");
    lang.className = "lang";
    lang.textContent = it.language || "Text";
    lang.style.setProperty("--tag", LANG_COLORS[(it.language || "").toLowerCase()] || "#0f6b56");
    label.appendChild(lang);
    if (it.filename) {
      var f = document.createElement("span");
      f.className = "fname";
      f.textContent = it.filename;
      f.title = it.filename;
      label.appendChild(f);
    }

    var copy = document.createElement("button");
    copy.type = "button";
    copy.className = "copy";
    copy.textContent = "কপি";
    copy.addEventListener("click", function () { copyText(it.code, copy); });

    bar.appendChild(label);
    bar.appendChild(copy);
    box.appendChild(bar);

    var pre = document.createElement("pre");
    var code = document.createElement("code");
    code.textContent = it.code;
    pre.appendChild(code);
    pre.tabIndex = 0;
    box.appendChild(pre);

    if (it.code.split("\n").length > COLLAPSE_LINES) {
      box.classList.add("collapsed");
      var more = document.createElement("button");
      more.type = "button";
      more.className = "more";
      more.textContent = "পুরোটা দেখুন";
      more.addEventListener("click", function () {
        var c = box.classList.toggle("collapsed");
        more.textContent = c ? "পুরোটা দেখুন" : "ছোট করুন";
      });
      box.appendChild(more);
    }
    return box;
  }

  /* ---------- copy ---------- */
  function copyText(text, btn) {
    function done(ok) {
      btn.textContent = ok ? "কপি হয়েছে" : "ব্যর্থ";
      btn.classList.toggle("done", ok);
      setTimeout(function () { btn.textContent = "কপি"; btn.classList.remove("done"); }, 1600);
    }
    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard.writeText(text).then(function () { done(true); }, function () { done(fallback(text)); });
    } else {
      done(fallback(text));
    }
  }
  function fallback(text) {
    var ta = document.createElement("textarea");
    ta.value = text;
    ta.setAttribute("readonly", "");
    ta.style.cssText = "position:fixed;opacity:0";
    document.body.appendChild(ta);
    ta.select();
    var ok = false;
    try { ok = document.execCommand("copy"); } catch (e) { ok = false; }
    document.body.removeChild(ta);
    return ok;
  }

  /* ---------- events ---------- */
  el.search.addEventListener("input", function () {
    state.query = el.search.value.trim().toLowerCase();
    if (state.data) renderMain();
  });
  el.msearch.addEventListener("input", function () {
    state.menuQuery = el.msearch.value;
    if (state.data) renderTree();
  });
  el.navBtn.addEventListener("click", function () { document.body.classList.toggle("nav-open"); });
  el.scrim.addEventListener("click", closeDrawer);
  document.addEventListener("keydown", function (e) { if (e.key === "Escape") closeDrawer(); });

  el.theme.addEventListener("click", function () {
    var root = document.documentElement;
    var cur = root.getAttribute("data-theme");
    var systemDark = window.matchMedia("(prefers-color-scheme: dark)").matches;
    var next = (cur ? cur === "dark" : systemDark) ? "light" : "dark";
    root.setAttribute("data-theme", next);
    try { localStorage.setItem("codecraft-theme", next); } catch (e) {}
  });
  try {
    var saved = localStorage.getItem("codecraft-theme");
    if (saved) document.documentElement.setAttribute("data-theme", saved);
  } catch (e) {}
})();
</script>
</body>
</html>",
      "created": "2026-09-21"
    }
  ]
}

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
add.py — "কোরআনের ফেরিওয়ালা" CodeCraft এ নতুন এন্ট্রি যোগ করার স্ক্রিপ্ট

ব্যবহার (index.html ও data.json এর ফোল্ডারে চালান):
    python add.py            নতুন এন্ট্রি যোগ করুন
    python add.py serve      লোকাল সার্ভার চালু করুন (পোর্ট 8000)
    python add.py serve 9000 অন্য পোর্টে চালু করুন
    python add.py list       মেনুর গাছ ও এন্ট্রির সংখ্যা দেখুন
    python add.py setup      প্রাথমিক মেনু + লোগো বিদ্যমান data.json এ যোগ করুন
    python add.py delete     একটি এন্ট্রি মুছুন
"""

import json
import os
import re
import shutil
import subprocess
import sys
import time
import urllib.parse
import urllib.request

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
DATA_FILE = os.path.join(BASE_DIR, "data.json")

SITE_TITLE = "কোরআনের ফেরিওয়ালা"
SITE_TAGLINE = "CodeCraft — স্ক্রিপ্ট, ফাইল ও নির্দেশনার সংগ্রহ"
ROOT_LABEL = "mj-ahmad"
LOGO_URL = "https://MJ-Ahmad.github.io/qf/assets/logo.png"

# প্রাথমিক মেনুর গাছ (সাব মেনু থাকলে {"name": …, "children": […]})
PRESET_MENUS = [
    "Systems",
    {"name": "Projects", "children": ["Quraner Fariwala", "MJSovereign"]},
    "README", "Git", "Python", "Node", "JSON", ".NET", "CLI", "Command", "Scripts",
]
SEP = " › "

# ফাইলের এক্সটেনশন থেকে ভাষা/লেবেল চেনার তালিকা
EXT_LANG = {
    ".html": "HTML", ".htm": "HTML", ".css": "CSS",
    ".json": "JSON", ".py": "Python",
    ".js": "Node", ".mjs": "Node", ".cjs": "Node",
    ".ts": "TypeScript", ".sh": "Bash", ".bash": "Bash", ".zsh": "Bash",
    ".php": "PHP", ".java": "Java", ".c": "C", ".cpp": "C++", ".cs": "C#",
    ".go": "Go", ".rs": "Rust", ".sql": "SQL",
    ".yml": "YAML", ".yaml": "YAML", ".xml": "XML",
    ".md": "Markdown", ".txt": "Text", ".env": "Text", ".ini": "Text",
}


# ------------------------------------------------------------ menu tree ----
def norm_nodes(lst):
    """মেনু তালিকাকে {name, children} গাছে বদলায় (পুরোনো ফরম্যাটও চলে)।"""
    out = []
    for m in lst or []:
        if isinstance(m, str):
            out.append({"name": m, "children": []})
        elif isinstance(m, dict) and m.get("name"):
            out.append({"name": m["name"], "children": norm_nodes(m.get("children"))})
    return out


def find_node(nodes, name):
    return next((n for n in nodes if n["name"] == name), None)


def children_of(tree, path):
    """path এর ভেতরের সন্তান-তালিকা ফেরত দেয় (না থাকলে তৈরি করে)।"""
    lst = tree
    for name in path:
        node = find_node(lst, name)
        if node is None:
            node = {"name": name, "children": []}
            lst.append(node)
        lst = node["children"]
    return lst


def merge_nodes(dst, src):
    """src এর মেনু dst এ যোগ করে; যা আগে থেকে আছে তা অক্ষত থাকে।"""
    for n in src:
        cur = find_node(dst, n["name"])
        if cur is None:
            dst.append({"name": n["name"], "children": []})
            cur = dst[-1]
        merge_nodes(cur["children"], n["children"])


def count_items(items, path):
    return sum(1 for it in items if it["path"][:len(path)] == path)


# ------------------------------------------------------------ data file ----
def normalize(data):
    """পুরোনো data.json (একস্তরের menu) নতুন গাছ-কাঠামোতে বদলায়।"""
    site = data.setdefault("site", {})
    if site.get("title") in (None, "", "CodeCraft"):
        site["title"] = SITE_TITLE
        site["tagline"] = SITE_TAGLINE
    if "tagline" not in site:
        site["tagline"] = site.pop("subtitle", SITE_TAGLINE)
    site.pop("subtitle", None)
    if site.get("logo") in (None, "", "logo.png"):
        site["logo"] = LOGO_URL
    site.setdefault("root_label", ROOT_LABEL)

    data["menus"] = norm_nodes(data.get("menus") or PRESET_MENUS)
    data.setdefault("items", [])
    for it in data["items"]:
        if not isinstance(it.get("path"), list) or not it["path"]:
            it["path"] = [it["menu"]] if it.get("menu") else []
        it.pop("menu", None)
        children_of(data["menus"], it["path"])   # মেনুর গাছে না থাকলে যোগ করে
    return data


def load_data():
    if not os.path.exists(DATA_FILE):
        return normalize({"site": {}, "menus": [], "items": []})
    with open(DATA_FILE, "r", encoding="utf-8") as f:
        return normalize(json.load(f))


def save_data(data):
    tmp = DATA_FILE + ".tmp"
    with open(tmp, "w", encoding="utf-8", newline="\n") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
        f.write("\n")
    os.replace(tmp, DATA_FILE)   # আধা-লেখা ফাইলে ডাটা নষ্ট হওয়া ঠেকায়


# ---------------------------------------------------------------- input ----
def ask(prompt, required=True, default=None):
    while True:
        suffix = f" [{default}]" if default else ""
        try:
            value = input(f"{prompt}{suffix}: ").strip()
        except EOFError:
            print("\nইনপুট শেষ হয়ে গেছে, বন্ধ করা হলো।")
            sys.exit(1)
        if not value and default:
            return default
        if value or not required:
            return value
        print("  ⚠ এটি খালি রাখা যাবে না।")


def ask_multiline(prompt):
    print(f"{prompt} (একাধিক লাইন লিখতে পারেন; শেষ করতে একটি খালি লাইনে Enter চাপুন)")
    lines = []
    while True:
        try:
            line = input("  > ")
        except EOFError:
            break
        if line == "":
            if lines:
                break
            print("  ⚠ বিবরণ খালি রাখা যাবে না।")
            continue
        lines.append(line)
    return "\n".join(lines)


def choose_path(data):
    """মেনু → সাব মেনু → সাব-সাব মেনু… ধাপে ধাপে নেমে গিয়ে পথ বেছে নেয়।"""
    path = []
    print(f"\nকোন মেনুর আওতায় যোগ করবেন?   ({data['site'].get('root_label', ROOT_LABEL)}/)")
    print("(মেনু বেছে ভেতরে ঢুকুন; দরকার হলে নতুন মেনু/সাব মেনু বানান; শেষে 0 দিয়ে সংরক্ষণ করুন)")
    while True:
        kids = children_of(data["menus"], path)
        print("\n  📂 " + (SEP.join(path) if path else data["site"].get("root_label", ROOT_LABEL) + "/"))
        for i, n in enumerate(kids, 1):
            total = count_items(data["items"], path + [n["name"]])
            sub = f", {len(n['children'])}টি সাব মেনু" if n["children"] else ""
            print(f"   {i}. {n['name']}  ({total}টি এন্ট্রি{sub})")
        new_no = len(kids) + 1
        print(f"   {new_no}. ➕ নতুন {'সাব মেনু' if path else 'মেনু'} তৈরি করুন")
        if path:
            print(f"   0. ✔ এখানেই সংরক্ষণ করুন  ({SEP.join(path)})")

        raw = ask("নম্বর লিখুন (অথবা সরাসরি নাম লিখুন)")
        if raw == "0" and path:
            return path
        if raw.isdigit():
            n = int(raw)
            if 1 <= n <= len(kids):
                path = path + [kids[n - 1]["name"]]
            elif n == new_no:
                path = path + [ask("নতুন নাম")]
            else:
                print("  ⚠ ভুল নম্বর।")
                continue
        else:
            path = path + [raw]   # সরাসরি নাম: থাকলে ঢুকবে, না থাকলে নতুন হবে
        children_of(data["menus"], path)   # নতুন হলে গাছে যোগ হয় (সেভ হবে শেষে)


# -------------------------------------------------------- file / source ----
def to_raw_github(url):
    m = re.match(r"^https?://github\.com/([^/]+)/([^/]+)/blob/(.+)$", url)
    if m:
        return f"https://raw.githubusercontent.com/{m.group(1)}/{m.group(2)}/{m.group(3)}"
    return url


def read_source(src):
    """(কোড, ফাইলের নাম) ফেরত দেয়। ব্যর্থ হলে None।"""
    if re.match(r"^https?://", src, re.I):
        url = to_raw_github(src)
        try:
            req = urllib.request.Request(url, headers={"User-Agent": "CodeCraft/1.0"})
            with urllib.request.urlopen(req, timeout=20) as resp:
                raw = resp.read()
        except Exception as e:
            print(f"  ⚠ লিংক থেকে আনা যায়নি: {e}")
            return None
        name = os.path.basename(urllib.parse.urlparse(url).path) or "file.txt"
    else:
        path = os.path.expanduser(src.strip('"').strip("'"))
        candidates = [path] if os.path.isabs(path) else [
            os.path.join(BASE_DIR, path),      # এই স্ক্রিপ্টের ফোল্ডারেই থাকলে
            os.path.join(os.getcwd(), path),   # বর্তমান টার্মিনাল ফোল্ডারে থাকলে
        ]
        found = next((p for p in candidates if os.path.isfile(p)), None)
        if not found:
            print("  ⚠ ফাইল পাওয়া যায়নি। নাম/পথ আবার দেখুন।")
            return None
        try:
            with open(found, "rb") as f:
                raw = f.read()
        except OSError as e:
            print(f"  ⚠ ফাইল পড়া যায়নি: {e}")
            return None
        name = os.path.basename(found)

    try:
        text = raw.decode("utf-8-sig")
    except UnicodeDecodeError:
        print("  ⚠ এটি টেক্সট ফাইল নয় (বা UTF-8 নয়)। ছবি/বাইনারি ফাইল যোগ করা যাবে না।")
        return None
    return text.replace("\r\n", "\n").rstrip("\n"), name


def read_pasted_code():
    print("কোড/টেক্সট পেস্ট করুন। শেষ করতে একটি আলাদা লাইনে শুধু END লিখুন।")
    lines = []
    while True:
        try:
            line = input()
        except EOFError:
            break
        if line.strip() == "END":
            break
        lines.append(line)
    return "\n".join(lines).rstrip("\n")


def guess_language(filename):
    return EXT_LANG.get(os.path.splitext(filename)[1].lower(), "Text")


# ------------------------------------------------------------- commands ----
def cmd_add():
    data = load_data()
    print("=" * 50)
    print(f"  {SITE_TITLE} — CodeCraft এ নতুন এন্ট্রি")
    print("=" * 50)

    path = choose_path(data)
    title = ask("\nহেডলাইন (শিরোনাম)")
    description = ask_multiline("\nবিবরণ")

    print("\nফাইলের লিংক (https://…) লিখুন, অথবা ফাইল একই ফোল্ডারে থাকলে শুধু ফাইলের নাম লিখুন।")
    print("ফাইল ছাড়া শুধু কোড পেস্ট করতে চাইলে খালি রেখে Enter চাপুন।")
    code = filename = None
    while code is None:
        src = ask("ফাইল লিংক / ফাইলের নাম", required=False)
        if not src:
            code = read_pasted_code()
            if not code:
                print("  ⚠ কিছুই পেস্ট করা হয়নি।")
                code = None
                continue
            filename = ask("ফাইলের নাম (যেমন app.py, না থাকলে খালি রাখুন)", required=False)
            break
        result = read_source(src)
        if result:
            code, filename = result

    language = ask("ভাষা/লেবেল (HTML, JSON, Python, Node…)", default=guess_language(filename or ""))

    data["items"].append({
        "id": str(time.time_ns() // 1_000_000),
        "path": path,
        "title": title,
        "description": description,
        "language": language,
        "filename": filename or "",
        "code": code,
        "created": time.strftime("%Y-%m-%d"),
    })
    save_data(data)

    print("\n✔ যোগ হয়েছে!")
    print(f"  মেনু    : {SEP.join(path)}")
    print(f"  হেডলাইন : {title}")
    print(f"  ভাষা    : {language}   ফাইল: {filename or '—'}   ({len(code.splitlines())} লাইন)")
    print("\nদেখতে চালান:  python add.py serve")


def cmd_setup():
    """প্রাথমিক মেনু, লোগো ও রুট-নাম বিদ্যমান data.json এ যোগ করে (কিছু মোছে না)।"""
    data = load_data()
    merge_nodes(data["menus"], norm_nodes(PRESET_MENUS))
    data["site"]["logo"] = LOGO_URL
    data["site"]["root_label"] = ROOT_LABEL
    save_data(data)
    print("✔ প্রাথমিক মেনু, লোগো ও রুট-নাম সেট হয়েছে। আগের এন্ট্রি অক্ষত আছে।")
    print()
    cmd_list()


def print_tree(nodes, items, path, depth):
    for n in nodes:
        p = path + [n["name"]]
        print("   " + "    " * depth + f"├─ {n['name']}  ({count_items(items, p)})")
        print_tree(n["children"], items, p, depth + 1)


def cmd_list():
    data = load_data()
    print(f"{data['site'].get('root_label', ROOT_LABEL)}/  — সব এন্ট্রি: {len(data['items'])}টি\n")
    print_tree(data["menus"], data["items"], [], 0)


def cmd_delete():
    data = load_data()
    if not data["items"]:
        print("মোছার মতো কোনো এন্ট্রি নেই।")
        return
    for i, it in enumerate(data["items"], 1):
        print(f"{i:>3}. [{SEP.join(it['path'])}] {it['title']}  ({it.get('language', '')} {it.get('filename', '')})")
    raw = ask("\nকোন নম্বরটি মুছবেন? (বাতিল করতে খালি রাখুন)", required=False)
    if not raw.isdigit() or not (1 <= int(raw) <= len(data["items"])):
        print("বাতিল করা হলো।")
        return
    it = data["items"][int(raw) - 1]
    if ask(f"“{it['title']}” মুছে ফেলবেন? (y/n)", default="n").lower() != "y":
        print("বাতিল করা হলো।")
        return
    data["items"].pop(int(raw) - 1)
    save_data(data)
    print("✔ মুছে ফেলা হয়েছে। (মেনুটি থেকে যাবে; দরকার হলে data.json থেকে মুছুন)")


def open_in_browser(url):
    """Termux হলে termux-open-url, নয়তো ডিফল্ট ব্রাউজার।"""
    try:
        if shutil.which("termux-open-url"):
            subprocess.Popen(["termux-open-url", url])
        else:
            import webbrowser
            webbrowser.open(url)
    except Exception:
        pass   # খুলতে না পারলে ব্যবহারকারী নিজেই লিংক খুলবেন


def cmd_serve(port):
    import functools
    import http.server
    import socketserver

    handler = functools.partial(http.server.SimpleHTTPRequestHandler, directory=BASE_DIR)
    socketserver.TCPServer.allow_reuse_address = True
    try:
        with socketserver.TCPServer(("127.0.0.1", port), handler) as httpd:
            url = f"http://localhost:{port}/index.html"
            print(f"{SITE_TITLE} চালু: {url}   (বন্ধ করতে Ctrl+C)")
            open_in_browser(url)
            httpd.serve_forever()
    except OSError as e:
        print(f"সার্ভার চালু করা যায়নি: {e}\nঅন্য পোর্ট দিন, যেমন: python add.py serve 9000")
    except KeyboardInterrupt:
        print("\nসার্ভার বন্ধ করা হলো।")


def main():
    args = sys.argv[1:]
    cmd = args[0].lower() if args else "add"
    try:
        if cmd == "add":
            cmd_add()
        elif cmd == "list":
            cmd_list()
        elif cmd == "setup":
            cmd_setup()
        elif cmd == "delete":
            cmd_delete()
        elif cmd == "serve":
            cmd_serve(int(args[1]) if len(args) > 1 and args[1].isdigit() else 8000)
        else:
            print(__doc__)
    except KeyboardInterrupt:
        print("\nবাতিল করা হলো।")


if __name__ == "__main__":
